import{z as B,x as d,o as E,c as A,q as l,j as r,D as i,d as t,s,S as n,b as e}from"./chunks/framework.C8m1ZpeB.js";const C=JSON.parse('{"title":"wait 与僵尸","description":"","frontmatter":{"title":"wait 与僵尸","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/wait-zombie.md","filePath":"cs/wait-zombie.md","lastUpdated":1791063341000}'),p={name:"cs/wait-zombie.md"};function c(m,a,D,P,w,u){const o=d("Mermaid");return E(),A("div",null,[a[2]||(a[2]=l('<h1 id="wait-与僵尸" tabindex="-1">wait 与僵尸 <a class="header-anchor" href="#wait-与僵尸" aria-label="Permalink to &quot;wait 与僵尸&quot;">​</a></h1><div class="epigraph"><p>子进程退出后仍要留下一块薄档案，直到父 wait 取走退出码；那份档案叫僵尸。</p><footer>—— 据 Silberschatz et al., Operating System Concepts；Tanenbaum MOS 整理</footer></div><p><a href="/cs/execve">上一课</a>让子可以换成新程序。子总要结束：用户调用退出，或内核因故障杀掉。缺口是：父需要一个<strong>同步点</strong>读到退出状态，而内核不能在子一结束就把 PCB 删光——否则状态没人收。本课钉 <code>wait</code>/<code>waitpid</code> 与僵尸态，不把 init 收孤儿写完。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>若子结束立即释放 PCB，父稍后 <code>wait</code> 会「查无此 PID」，退出码丢失。若子结束仍占全部用户页，资源泄漏。折中：丢掉地址空间与打开文件，留下极瘦的 PCB（PID、退出码、统计），状态为僵尸；父 <code>wait</code> 读走后才真正释放 PCB。缺口不是 <code>exec</code> 的加载，而是这条收割协议。</p><p><span class="marginnote">僵尸不是故障进程在跑，它不占 CPU、不占用户内存。故障是父永不 wait：瘦 PCB 会堆积，PID 空间被占。</span></p><p><span class="marginnote">给泄漏一个数字实例：Linux 默认 PID 上限约 32768（可用 <code>/proc/sys/kernel/pid_max</code> 调大）；一个永不 wait 的父进程每 fork 一次就漏一个僵尸，PID 被占满后系统将再也创建不出任何新进程。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>子退出：进入僵尸，向父发信号（后课信号课已给出 <code>SIGCHLD</code> 直觉）。父 <code>wait</code>：若有僵尸孩子，拷退出码，释放该 PCB，返回 PID；若无则阻塞，直到有子退出或被信号打断（<a href="/cs/restart-syscall">重启系统调用</a>）。<code>WNOHANG</code> 不阻塞。可指定 PID 或进程组，精确匹配是后课进程组。</p>',9)),(E(),r(n,null,{default:i(()=>[s(o,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20RUN%5B%22%E5%AD%90%E8%BF%90%E8%A1%8C%22%5D%20--%3E%20EXIT%5B%22%E9%80%80%E5%87%BA%3A%20%E9%87%8A%E7%94%A8%E6%88%B7%E8%B5%84%E6%BA%90%22%5D%0A%20%20EXIT%20--%3E%20Z%5B%22%E5%83%B5%E5%B0%B8%20PCB%22%5D%0A%20%20Z%20--%3E%20WAIT%5B%22%E7%88%B6%20wait%3A%20%E8%AF%BB%E7%A0%81%E5%B9%B6%E9%87%8A%E6%94%BE%22%5D%0A"})]),fallback:i(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,[e("span",{class:"marginnote"},[t("「会合」翻译成大白话：父子约好在退出码这个信箱交接——子把码放进僵尸档案（先到），父调 wait 来取（后到），谁先到都不丢东西。"),e("code",null,"WNOHANG"),t(" 则是把「阻塞等信」改成「瞄一眼就走」。")])],-1)),a[4]||(a[4]=e("p",null,"多子：wait 一次收一个；循环直到关心的都收完。",-1)),a[5]||(a[5]=e("h2",{id:"机制",tabindex:"-1"},[t("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[6]||(a[6]=e("p",null,"僵尸把「进程已死」与「身份仍可查询」分开。调度器看不见僵尸（不在就绪队列）。父与子的同步是一次会合：类似完成量，对象是退出码。没有 wait，内核仍须保留 PID，以免新进程立刻复用该 PID、让父收到错误的孩子。",-1)),(E(),r(n,null,{default:i(()=>[s(o,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20EXIT2%5B%22%E5%AD%90%E8%BF%9B%E7%A8%8B%E9%80%80%E5%87%BA%22%5D%20--%3E%20REL%5B%22%E9%87%8A%E6%94%BE%E5%9C%B0%E5%9D%80%E7%A9%BA%E9%97%B4%E4%B8%8E%E6%89%93%E5%BC%80%E6%96%87%E4%BB%B6%22%5D%0A%20%20REL%20--%3E%20KEEP%5B%22%E4%BF%9D%E7%95%99%E7%98%A6%20PCB%3A%20PID%2B%E9%80%80%E5%87%BA%E7%A0%81%2B%E7%BB%9F%E8%AE%A1%22%5D%0A%20%20KEEP%20--%3E%20SIG%5B%22%E5%90%91%E7%88%B6%E5%8F%91%20SIGCHLD%22%5D%0A%20%20SIG%20--%3E%20Q%7B%22%E7%88%B6%E8%B0%83%E7%94%A8%20wait%20%E5%90%97%3F%22%7D%0A%20%20Q%20--%20%E6%98%AF%20--%3E%20REAP%5B%22%E6%8B%B7%E8%B5%B0%E9%80%80%E5%87%BA%E7%A0%81%2C%20%E9%87%8A%E6%94%BE%20PCB%22%5D%0A%20%20Q%20--%20%E5%90%A6%20--%3E%20STAY%5B%22%E5%83%B5%E5%B0%B8%E6%BB%9E%E7%95%99%2C%20%E7%99%BD%E5%8D%A0%E4%B8%80%E4%B8%AA%20PID%22%5D%0A%20%20REAP%20--%3E%20FREE%5B%22PID%20%E6%89%8D%E5%8F%AF%E8%A2%AB%E5%A4%8D%E7%94%A8%22%5D%0A"})]),fallback:i(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=l('<p><span class="marginnote">常见误区：把僵尸当成「还在跑的坏进程」去 kill。kill 对僵尸无效——它已经死了；要治的是它的父进程（让父 wait，或让父退出把孩子过继给 init）。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把 <code>waitid</code> 的全部选项背完。父先于子退出时僵尸交给谁，下一课孤儿与 init。也不把线程退出与进程退出混成一次 wait：进程退出码是线程组的代表。</p><p>后课默认：活着的父必须收僵尸。父先走时孩子不能没人收，下一课讲孤儿与 init。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>子先释用户资源，留僵尸 PCB；父 wait 取码后才释放控制块。</li><li>永不 wait 会堆积 PID。</li><li>父先退出是下一课孤儿。</li><li>出处：Silberschatz et al., <em>OSC</em>；Tanenbaum and Bos, <em>MOS</em>。</li></ul>',6))])}const f=B(p,[["render",c]]);export{C as __pageData,f as default};
